namespace sv_61ff00929c634a2db2458ce48552ff0b.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Every SignalR circuit (user) gets its own instance.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public Theme Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Theme or AccentColor changes.
    /// Interactive components subscribe to this to re-render.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Apply both values at once, raising only a single notification.
    /// </summary>
    public void SetPreferences(Theme theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island embedded in the static layout header.
   Because it has @rendermode InteractiveServer, it lives in the
   circuit and re-renders when ThemeService raises OnChange. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge rounded-pill"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@* Interactive island in the sidebar for quick theme switching. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="px-3 py-2">
    <label class="form-label text-light mb-1" style="font-size: .8rem;">Theme</label>
    <select class="form-select form-select-sm"
            value="@ThemeService.Theme"
            @onchange="OnThemeChanged">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
        {
            ThemeService.Theme = theme;
        }
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label">Theme</label>
            <select class="form-select"
                    value="@_theme"
                    @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color"
                       class="form-control form-control-color"
                       value="@_accentColor"
                       @onchange="OnAccentColorChanged" />
                <span class="text-muted">@_accentColor</span>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="Save"
                style="background-color: @_accentColor; border-color: @_accentColor;">
            Save Preferences
        </button>
    </div>
</div>

<div class="mt-3">
    <h5>Live Preview</h5>
    <div class="p-3 rounded"
         style="background-color: @(_theme == Theme.Dark ? "#1a1a2e" : "#f8f9fa");
                color: @(_theme == Theme.Dark ? "#eee" : "#222");
                border: 2px solid @_accentColor;">
        This panel reflects your unsaved selections.
        Hit <strong>Save</strong> to push changes app-wide.
    </div>
</div>

@code {
    private Theme _theme;
    private string _accentColor = string.Empty;

    protected override void OnInitialized()
    {
        _theme = ThemeService.Theme;
        _accentColor = ThemeService.AccentColor;
        ThemeService.OnChange += OnServiceChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
            _theme = theme;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        _accentColor = e.Value?.ToString() ?? _accentColor;
    }

    private void Save()
    {
        ThemeService.SetPreferences(_theme, _accentColor);
    }

    private void OnServiceChanged()
    {
        _theme = ThemeService.Theme;
        _accentColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnServiceChanged;
    }
}

