@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <div class="mb-3">
            <label class="form-label">Theme</label>
            <select class="form-select"
                    value="@_theme"
                    @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color"
                       class="form-control form-control-color"
                       value="@_accentColor"
                       @onchange="OnAccentColorChanged" />
                <span class="text-muted">@_accentColor</span>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="Save"
                style="background-color: @_accentColor; border-color: @_accentColor;">
            Save Preferences
        </button>
    </div>
</div>

<div class="mt-3">
    <h5>Live Preview</h5>
    <div class="p-3 rounded"
         style="background-color: @(_theme == Theme.Dark ? "#1a1a2e" : "#f8f9fa");
                color: @(_theme == Theme.Dark ? "#eee" : "#222");
                border: 2px solid @_accentColor;">
        This panel reflects your unsaved selections.
        Hit <strong>Save</strong> to push changes app-wide.
    </div>
</div>

@code {
    private Theme _theme;
    private string _accentColor = string.Empty;

    protected override void OnInitialized()
    {
        _theme = ThemeService.Theme;
        _accentColor = ThemeService.AccentColor;
        ThemeService.OnChange += OnServiceChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
            _theme = theme;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        _accentColor = e.Value?.ToString() ?? _accentColor;
    }

    private void Save()
    {
        ThemeService.SetPreferences(_theme, _accentColor);
    }

    private void OnServiceChanged()
    {
        _theme = ThemeService.Theme;
        _accentColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnServiceChanged;
    }
}

